input.sparql:
SELECT ?z ?tp ?sp WHERE {
  ?z a brick:Zone ; brick:hasName "Core_mid" .
  ?z brick:hasTemperature ?t .
  ?t ref:hasExternalReference ?tp .
  ?tp ref:hasTimeseriesId ?tsid .
}

SELECT ?z ?sp WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?name .
  FILTER (CONTAINS(?name, "Core_mid"))
}

SELECT ?p ?pcls ?tsid WHERE {
  ?p brick:hasLocation <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F2_Z01> .
  ?p a ?pcls .
  OPTIONAL { ?p ref:hasExternalReference ?e . ?e ref:hasTimeseriesId ?tsid }
} LIMIT 200

SELECT ?p ?pcls ?tsid WHERE {
  ?sp a brick:Cooling_Setpoint .
  ?sp brick:hasLocation <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F2_Z01> .
  OPTIONAL { ?sp ref:hasExternalReference ?e . ?e ref:hasTimeseriesId ?tsid }
  BIND(?sp AS ?p)
  BIND(?sp AS ?pcls)
} LIMIT 200

